import re, sys

TE = r'ఀ-౿'
has_te = re.compile(f'[{TE}]')

def esc(s):
    return s.replace('\\', '\\\\').replace("'", "\\'")

def make_L(en, te):
    return f"L('{esc(en.strip())}', '{esc(te.strip())}')"

def split_bi(content):
    # Only handle a single ' / ' split with Telugu on the right side.
    parts = content.split(' / ')
    if len(parts) != 2:
        return None
    en, te = parts
    if not has_te.search(te) or has_te.search(en):
        return None
    if not en.strip():
        return None
    return en, te

def process(text):
    skipped = []
    out = []
    i = 0
    n = len(text)
    # Tokenize-ish line by line to keep it simple and safe.
    lines = text.split('\n')
    new_lines = []
    for lineno, line in enumerate(lines, 1):
        if ' / ' not in line or not has_te.search(line):
            new_lines.append(line); continue
        original = line

        # Case 1: JSX attribute  attr="A / తె"  or attr='A / తె'
        def attr_repl(m):
            q = m.group('q'); content = m.group('c')
            sp = split_bi(content)
            if not sp: return m.group(0)
            return f"{m.group('pre')}={{{make_L(*sp)}}}"
        line = re.sub(r"(?P<pre>\b[\w-]+)=(?P<q>[\"'])(?P<c>[^\"']*? / [^\"']*?)(?P=q)", attr_repl, line)

        # Case 2: plain quoted JS string  '...A / తె...'  or "..."
        def str_repl(m):
            q = m.group('q'); content = m.group('c')
            sp = split_bi(content)
            if not sp: return m.group(0)
            return make_L(*sp)
        line = re.sub(r"(?P<q>[\"'])(?P<c>[^\"']*? / [^\"']*?)(?P=q)", str_repl, line)

        # Case 3: pure JSX text node  >A / తె<   (no braces/tags inside)
        def jsx_repl(m):
            content = m.group('c')
            sp = split_bi(content)
            if not sp: return m.group(0)
            return f">{{{make_L(*sp)}}}<"
        line = re.sub(r">(?P<c>[^<>{}]*? / [^<>{}]*?)<", jsx_repl, line)

        if line == original and ' / ' in original and has_te.search(original):
            skipped.append((lineno, original.strip()))
        new_lines.append(line)
    return '\n'.join(new_lines), skipped

if __name__ == '__main__':
    path = sys.argv[1]
    apply = '--apply' in sys.argv
    src = open(path, encoding='utf-8').read()
    new, skipped = process(src)
    if apply:
        open(path, 'w', encoding='utf-8').write(new)
        print(f"APPLIED {path}")
    else:
        print(f"--- DRY RUN {path} ---")
        # show diff-ish
        for a,b in zip(src.split('\n'), new.split('\n')):
            if a!=b:
                print(f"-  {a.strip()}")
                print(f"+  {b.strip()}")
    if skipped:
        print(f"  [SKIPPED {len(skipped)} complex lines in {path}]")
        for ln, s in skipped:
            print(f"    L{ln}: {s[:110]}")
