import re, sys

def find_component_bodies(lines):
    """Yield (open_brace_line_idx) for each PascalCase function/const-arrow component."""
    starts = []
    for i, ln in enumerate(lines):
        if re.search(r'\bfunction [A-Z]\w*\s*\(', ln) or re.search(r'\bconst [A-Z]\w*\s*=\s*\(', ln) or re.search(r'\bconst [A-Z]\w*:\s*React\.', ln):
            starts.append(i)
    return starts

def body_range(lines, start):
    # find opening brace of body (paren depth back to 0, line ends with {)
    depth = 0; seen = False
    for i in range(start, min(start+40, len(lines))):
        depth += lines[i].count('(') - lines[i].count(')')
        if '(' in lines[i]: seen = True
        if seen and depth <= 0 and lines[i].rstrip().endswith('{'):
            open_idx = i
            break
    else:
        return None
    # find matching close brace
    bdepth = 0; started=False
    for j in range(open_idx, len(lines)):
        bdepth += lines[j].count('{') - lines[j].count('}')
        if lines[j].count('{')>0: started=True
        if started and bdepth == 0:
            return (open_idx, j)
    return (open_idx, len(lines)-1)

for path in sys.argv[1:]:
    s = open(path, encoding='utf-8').read()
    lines = s.split('\n')
    inserts = []  # (after_idx, indent)
    for st in find_component_bodies(lines):
        rng = body_range(lines, st)
        if not rng: continue
        o, c = rng
        body = '\n'.join(lines[o:c+1])
        if 'L(' in body and '= useLang()' not in body:
            indent = re.match(r'\s*', lines[o+1] if o+1 < len(lines) else '  ').group(0) or '  '
            inserts.append((o, indent))
    # apply bottom-up
    for o, indent in sorted(set(inserts), reverse=True):
        lines.insert(o+1, f"{indent}const {{ L }} = useLang()")
    if inserts:
        open(path,'w',encoding='utf-8').write('\n'.join(lines))
        print(f"{path}: inserted {len(inserts)} hooks")
