            <li>{L('Delivery fee (if any) is cash to the rider, not part of the online refund.', 'డెలివరీ ఫీజు (ఉంటే) రైడర్‌కు నగదు, ఆన్‌లైన్ రీఫండ్‌లో భాగం కాదు.')}</li>
          </ul>
        </div>

        {/* Support */}
        <div className="bg-white rounded-2xl border border-gray-100 p-4">
          <p className="font-extrabold text-gray-900 text-sm">{L('Need help with an order?', 'ఆర్డర్‌తో సహాయం కావాలా?')}</p>
          <p className="text-xs text-gray-600 mt-1">
            {L('Keep your Order ID ready (e.g. YFF-…) and reach us:', 'మీ ఆర్డర్ ID (ఉదా. YFF-…) సిద్ధంగా ఉంచుకుని మమ్మల్ని సంప్రదించండి:')}
          </p>
          <div className="mt-3 space-y-2">
            {SUPPORT_PHONE ? (
              <>
                <a href={`tel:+${SUPPORT_PHONE}`} className="block w-full text-center bg-green-700 text-white font-bold py-3 rounded-xl text-sm active:bg-green-800">
                  {L('📞 Call support', 'కాల్ చేయండి')}
                </a>
                {waLink && (
                  <a href={waLink} target="_blank" rel="noopener noreferrer" className="block w-full text-center bg-green-600 text-white font-bold py-3 rounded-xl text-sm active:bg-green-700">
                    {L('💬 WhatsApp support', 'వాట్సాప్')}
                  </a>
                )}
              </>
            ) : (
              <p className="text-xs text-gray-500">
                {L('Contact your farmer directly from the order page, or reach the YourFamilyFarmer team.', 'ఆర్డర్ పేజీ నుండి నేరుగా రైతును సంప్రదించండి, లేదా YourFamilyFarmer బృందాన్ని సంప్రదించండి.')}
              </p>
            )}
            {SUPPORT_EMAIL && (
              <a href={`mailto:${SUPPORT_EMAIL}`} className="block text-center text-sm font-bold text-green-700 underline">
                ✉️ {SUPPORT_EMAIL}
              </a>
            )}
          </div>
        </div>
      </div>
    </main>
  )
}

